def transform(wb):
    ws = wb['Sheet1']
    for row in (7, 6, 5, 4, 3, 2, 1):
        i_val = ws.cell(row=row, column=9).value
        h_val = ws.cell(row=row, column=8).value
        if i_val is not None and i_val != '' and (h_val is None or h_val == ''):
            ws.delete_rows(row, 1)
    return None
